# Generated by build.py from recipe.yml for recipe http-serve-one-folder-every-way. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'plain' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/hello.txt'), "hello from surl`n")
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--directory', 'site', 'http://127.0.0.1:8080/', 'ftp://127.0.0.1:8081/', 'tftp://127.0.0.1:8080/', 'gopher://127.0.0.1:8082/', 'dict://127.0.0.1:8083/', 'ws://127.0.0.1:8084/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s http://127.0.0.1:8080/hello.txt ftp://127.0.0.1:8081/hello.txt tftp://127.0.0.1:8080/hello.txt gopher://127.0.0.1:8082/0/hello.txt dict://127.0.0.1:8083/d:hello.txt ws://127.0.0.1:8084/hello.txt } finally { Stop-Process $server0 }
